#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_OUTGOING FW_INCOMING_WAN_DMZ FW_OUTGOING_DMZWAN FW_OUTGOING_LANDMZ FW_1TO1_NAT FW_NAT; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_PORT fws_apps_web-browsing_ssl && fail 'a port group named fws_apps_web-browsing_ssl exists; nothing was written'
named FW_GROUP_IP fws_dns-servers && fail 'an IP group named fws_dns-servers exists; nothing was written'
named FW_GROUP_IP fws_admin-range && fail 'an IP group named fws_admin-range exists; nothing was written'
named FW_GROUP_IP fws_dmz-servers && fail 'an IP group named fws_dmz-servers exists; nothing was written'
named FW_GROUP_PORT fws_apps_modbus_siemens-s7 && fail 'a port group named fws_apps_modbus_siemens-s7 exists; nothing was written'
named FW_GROUP_PORT fws_App-Server-Ports && fail 'a port group named fws_App-Server-Ports exists; nothing was written'
named FW_GROUP_IP fws_updates.example.com && fail 'an IP group named fws_updates.example.com exists; nothing was written'
named FW_GROUP_IP fws_Not-From-Guests_src && fail 'an IP group named fws_Not-From-Guests_src exists; nothing was written'
named FW_GROUP_IP fws_all-servers && fail 'an IP group named fws_all-servers exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_dns-servers --set .COMMENT 'FWShift: dns-servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.0.2.53-192.0.2.54
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_admin-range --set .COMMENT 'FWShift: admin-range'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.5.10-10.10.5.20
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_dmz-servers --set .COMMENT 'FWShift: dmz-servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.25
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_updates.example.com --set .COMMENT 'FWShift: updates.example.com'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP updates.example.com
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Not-From-Guests_src --set .COMMENT 'FWShift: not 10.10.200.0/24'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 0.0.0.0-10.10.199.255
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.201.0-255.255.255.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_all-servers --set .COMMENT 'FWShift: all-servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.25
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.0.2.53-192.0.2.54
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_apps_web-browsing_ssl --set .COMMENT 'FWShift: apps_web-browsing_ssl'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_apps_modbus_siemens-s7 --set .COMMENT 'FWShift: apps_modbus_siemens-s7'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 102
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 502
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_App-Server-Ports --set .COMMENT 'FWShift: App-Server-Ports'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8080
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 9000-9010
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'Allow-Web-Out: Outbound web for the "office" LAN'
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_apps_web-browsing_ssl
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT Allow-DNS
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_dns-servers
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO udp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT Allow-DNS
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_dns-servers
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.10 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT Inbound-Web
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 10.20.0.25 --set .IN_PORT 25 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT Inbound-Mail
N=$((N+1))

# FW_OUTGOING_DMZWAN
N=$(rows FW_OUTGOING_DMZWAN)
gc --silent --goto FW_OUTGOING_DMZWAN --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT Allow-DNS
gc --silent --set-refname "FW_OUTGOING_DMZWAN.$N.IN_IP" fws_dns-servers
N=$((N+1))
gc --silent --goto FW_OUTGOING_DMZWAN --add-row --set .PROTO udp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT Allow-DNS
gc --silent --set-refname "FW_OUTGOING_DMZWAN.$N.IN_IP" fws_dns-servers
N=$((N+1))

# FW_OUTGOING_LANDMZ
N=$(rows FW_OUTGOING_LANDMZ)
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 10.20.0.10 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT App-Server-Ports
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_PORT" fws_App-Server-Ports
N=$((N+1))

# FW_1TO1_NAT
N=$(rows FW_1TO1_NAT)
gc --silent --goto FW_1TO1_NAT --add-row --set .LOCAL_NET 10.20.0.25 --set .REMOTE_NET 203.0.113.25 --set .MASK 32 --set .ENABLE_ARP yes --set .COMMENT Mail-Static
N=$((N+1))

# FW_NAT
N=$(rows FW_NAT)
gc --goto FW_NAT --add-row --set .EXT_IF ext1 --set .IN_IP 0.0.0.0/0 --set .COMMENT Outbound-PAT
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
